import { useState } from 'react';

const Counter = () => {
  const [count, setCount] = useState(0);

  return (
    <div>
      <h1>Counter: {count}</h1>
      <button onClick={() => setCount(count - 1)}>-</button>
      <button onClick={() => setCount(0)}>Reset</button>
      <button onClick={() => setCount(count + 1)}>+</button>
    </div>
  );
};

show(<Counter />);

import {useState} from 'react';

const TailwindCard = () => {
  const [likes, setLikes] = useState(42);
  const [isLiked, setIsLiked] = useState(false);
  const [activeTab, setActiveTab] = useState('metrics');

  const handleLike = () => {
    setLikes(prev => (isLiked ? prev - 1 : prev + 1));
    setIsLiked(!isLiked);
  };

  return (
    <div
      className="p-6 max-w-md mx-auto bg-slate-900 text-slate-100 rounded-2xl shadow-xl border border-
  slate-800 transition-all"
    >
      {/* Header */}
      <div className="flex items-center justify-between pb-4 border-b border-slate-800">
        <div className="flex items-center space-x-3">
          <div
            className="w-10 h-10 rounded-xl bg-sky-500/10 border border-sky-500/20 flex items-center
  justify-center text-sky-400 font-bold"
          >
            NP
          </div>
          <div>
            <h3 className="font-semibold text-white leading-tight">
              NovaPad Live
            </h3>
            <p className="text-xs text-slate-400">Tailwind CSS Component</p>
          </div>
        </div>
        <span
          className="px-2.5 py-1 text-xs font-medium bg-emerald-500/10 text-emerald-400 border border-
  emerald-500/20 rounded-full"
        >
          Active
        </span>
      </div>

      {/* Tabs */}
      <div className="flex space-x-2 my-4 bg-slate-800/60 p-1 rounded-lg">
        {['metrics', 'activity'].map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`flex-1 py-1.5 text-xs font-medium rounded-md capitalize transition-colors ${
              activeTab === tab
                ? 'bg-sky-500 text-white shadow-sm'
                : 'text-slate-400 hover:text-slate-200'
            }`}
          >
            {tab}
          </button>
        ))}
      </div>

      {/* Dynamic Content */}
      {activeTab === 'metrics' ? (
        <div className="grid grid-cols-2 gap-3 mb-5">
          <div className="p-3 bg-slate-800/40 rounded-xl border border-slate-800">
            <span className="text-xs text-slate-400">Bundler Speed</span>
            <p className="text-lg font-bold text-sky-400 mt-1">~12ms</p>
          </div>
          <div className="p-3 bg-slate-800/40 rounded-xl border border-slate-800">
            <span className="text-xs text-slate-400">Memory Load</span>
            <p className="text-lg font-bold text-emerald-400 mt-1">Optimized</p>
          </div>
        </div>
      ) : (
        <div className="p-3 bg-slate-800/40 rounded-xl border border-slate-800 mb-5 text-xs text-slate-300">
          <p>
            ⚡ esbuild bundled code successfully into the isolated preview
            frame.
          </p>
        </div>
      )}

      {/* Footer Action */}
      <div className="flex items-center justify-between pt-2">
        <span className="text-xs text-slate-400 font-mono">
          {likes} total likes
        </span>
        <button
          onClick={handleLike}
          className={`flex items-center space-x-1.5 px-4 py-2 rounded-xl text-xs font-semibold transition-
  all transform active:scale-95 ${
    isLiked
      ? 'bg-sky-500 text-white shadow-md shadow-sky-500/25'
      : 'bg-slate-800 text-slate-300 hover:bg-slate-700'
  }`}
        >
          <span>{isLiked ? '💙' : '🤍'}</span>
          <span>{isLiked ? 'Liked' : 'Like'}</span>
        </button>
      </div>
    </div>
  );
};

show(<TailwindCard />);
